#include <cstdint>
#include <iostream>
#include <map>
#include <string>
#include <variant>

using Value = std::variant<std::uint32_t, std::uint64_t, std::string>;

struct Key
{
    std::map<std::string, Value> values{};
    std::map<std::string, Key> children{};
};

int main()
{
    Key root{};
    root.children["Software"].children["Xenon"].values["Width"] = std::uint32_t{1280};
}
